using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — resolves any type.
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probes without throwing.
//    With the default resolver every type resolves, so Person succeeds:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGetTypeInfo<Person> → resolved ({info!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Person> → not available");

// Build options that use a custom context exposing *only* Person.
var limited = new JsonSerializerOptions { TypeInfoResolver = LimitedContext.Default };

// Person is in the context → succeeds
if (limited.TryGetTypeInfo<Person>(out _))
    Console.WriteLine("TryGetTypeInfo<Person>  (limited) → resolved ✓");

// Order is NOT in the context → returns false, no exception
if (limited.TryGetTypeInfo<Order>(out _))
    Console.WriteLine("TryGetTypeInfo<Order>   (limited) → resolved");
else
    Console.WriteLine("TryGetTypeInfo<Order>   (limited) → not available ✗");

// --- Types ------------------------------------------------------------------

public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// Source-generated context that only includes Person.
[JsonSerializable(typeof(Person))]
public partial class LimitedContext : JsonSerializerContext;

